actions.script:
// ArtifactHitBin is written by the server as screens, services and entities are used; when it has no rows
// (tracking off, a fresh database) the report shows an inline sample and says so.
usingFallback = false
if (!allBinList || allBinList.length === 0) {
    usingFallback = true
    const base = new Date(); base.setHours(0, 0, 0, 0)
    const pad = (n) => String(n).padStart(2, '0')
    const stamp = (dayBack, hour) => { const d = new Date(base.getTime() - dayBack * 86400000); d.setHours(hour)
        return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())} ${pad(hour)}:00:00` }
    const names = [['AT_XML_SCREEN', 'screen', 'webroot.qapps.gallery.List'], ['AT_XML_SCREEN', 'screen', 'webroot.qapps.gallery.Detail'],
        ['AT_XML_SCREEN_TRANS', 'transition', 'webroot.qapps.gallery.List.searchEnum'], ['AT_SERVICE', 'entity-auto', 'update#moqui.basic.Enumeration'],
        ['AT_ENTITY', 'list', 'moqui.basic.Enumeration'], ['AT_ENTITY', 'one', 'moqui.security.UserAccount'], ['AT_REST_PATH', 'get', 'rest/e1/moqui.basic.Geo']]
    const sample = []
    let seq = 1
    for (let day = 6; day >= 0; day--) names.forEach((n, i) => {
        const hits = 12 + ((day * 7 + i * 5) % 40)
        const avg = 3 + ((i * 13 + day) % 60)
        sample.push({ hitBinId: String(seq++), artifactType: n[0], artifactSubType: n[1], artifactName: n[2],
            binStartDateTime: stamp(day, 9), binEndDateTime: stamp(day, 10), hitCount: hits,
            totalTimeMillis: hits * avg, minTimeMillis: 1, maxTimeMillis: avg * 4, slowHitCount: i === 3 ? 2 : 0 })
    })
    allBinList = sample
    // the first page of the sample, with the fields the list's nav row reads
    const pageSize = 20
    hitBinList = sample.slice(0, pageSize)
    hitBinListCount = sample.length
    hitBinListPageIndex = 0
    hitBinListPageSize = pageSize
    hitBinListPageMaxIndex = Math.floor((sample.length - 1) / pageSize)
    hitBinListPageRangeLow = 1
    hitBinListPageRangeHigh = Math.min(pageSize, sample.length)
}

// artifact types for the parameter drop-down: from the data, else from the sample
const typeNames = typeList && typeList.length ? typeList.map((row) => row.artifactType).filter((name) => name)
    : Array.from(new Set(allBinList.map((row) => row.artifactType)))
typeOptionList = typeNames.map((name) => ({ artifactType: name }))

// the numbers and the chart series over the whole filtered set
// a number-decimal field is a decimal object in a script: toNumber(), not Number()
const num = (v) => (v === null || v === undefined ? 0 : (typeof v === 'object' && typeof v.toNumber === 'function' ? v.toNumber() : Number(v)))
let hits = 0, time = 0, slow = 0, maxTime = 0
const byType = new Map(), byDay = new Map(), nameSet = new Set()
allBinList.forEach((row) => {
    const h = num(row.hitCount), tt = num(row.totalTimeMillis)
    hits += h; time += tt; slow += num(row.slowHitCount); maxTime = Math.max(maxTime, num(row.maxTimeMillis))
    nameSet.add(row.artifactName)
    byType.set(row.artifactType, (byType.get(row.artifactType) || 0) + h)
    // a date-time field is a timestamp object whose text is epoch milliseconds: the day comes from
    // ec.l10n.format as the display widget does it; the sample rows hold date text
    const start = row.binStartDateTime
    let day = ''
    try { day = String(ec.l10n.format(start, 'yyyy-MM-dd')) } catch (e) { day = '' }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(day)) {
        const text = String(start)
        day = /^\d+$/.test(text) ? new Date(Number(text)).toISOString().slice(0, 10) : text.slice(0, 10)
    }
    const cur = byDay.get(day) || { hits: 0, time: 0 }
    cur.hits += h; cur.time += tt; byDay.set(day, cur)
})
const dayKeys = Array.from(byDay.keys()).sort()
cardHits = ec.l10n.format(hits, '#,##0')
cardArtifacts = ec.l10n.format(nameSet.size, '#,##0')
cardAvg = ec.l10n.format(hits ? time / hits : 0, '#,##0.0')
cardSlow = ec.l10n.format(slow, '#,##0')
slowClass = slow ? 'text-warning' : ''
cardMax = ec.l10n.format(maxTime, '#,##0')
binCount = ec.l10n.format(allBinList.length, '#,##0')
typeLabelsJson = JSON.stringify(Array.from(byType.keys()))
typeHitsJson = JSON.stringify(Array.from(byType.values()))
dayLabelsJson = JSON.stringify(dayKeys.map((d) => d.slice(5)))
dayHitsJson = JSON.stringify(dayKeys.map((d) => byDay.get(d).hits))
dayAvgJson = JSON.stringify(dayKeys.map((d) => { const c = byDay.get(d); return c.hits ? Math.round(c.time / c.hits * 10) / 10 : 0 }))
// the totals row of the table, over the whole filtered set
totalsMap = { artifactName: 'Total of ' + allBinList.length + ' bins', hitCount: hits, totalTimeMillis: time,
    averageTime: hits ? time / hits : 0, maxTimeMillis: maxTime, slowHitCount: slow }

render-mode.text:
{"t": "dashboard", "id": "ReportCards", "c": [
    {"t": "numberCard", "id": "ReportHits", "title": "Hits", "value": ${JSON.stringify(cardHits + ' in ' + binCount + ' bins')}},
    {"t": "numberCard", "id": "ReportArtifacts", "title": "Artifacts", "value": ${JSON.stringify(cardArtifacts + ' distinct names')}},
    {"t": "numberCard", "id": "ReportAverage", "title": "Average time", "value": ${JSON.stringify(cardAvg + ' ms, max ' + cardMax + ' ms')}},
    {"t": "numberCard", "id": "ReportSlow", "title": "Slow hits (over 2.6 std dev)", "value": ${JSON.stringify(String(cardSlow))}}
]}
